~/.bun/bin/bun -e "
const g = await Bun.file('googlesuper_tools.json').json();
const h = await Bun.file('github_tools.json').json();

function hasDefsKey(obj) {
  if (!obj || typeof obj !== 'object') return false;
  if (Array.isArray(obj)) return obj.some(hasDefsKey);
  if (Object.prototype.hasOwnProperty.call(obj, '\$defs')) return true;
  return Object.values(obj).some(hasDefsKey);
}
function countRefs(obj) {
  if (!obj || typeof obj !== 'object') return 0;
  if (Array.isArray(obj)) return obj.reduce((a,v) => a + countRefs(v), 0);
  let c = 0;
  for (const [k,v] of Object.entries(obj)) {
    if (k === '\$ref') c++;
    c += countRefs(v);
  }
  return c;
}

for (const [name, list] of [['googlesuper', g], ['github', h]]) {
  let withDefsKey = 0, withRefs = 0, refsButNoDefs = 0;
  for (const t of list) {
    const has = hasDefsKey(t);
    const refs = countRefs(t);
    if (has) withDefsKey++;
    if (refs > 0) withRefs++;
    if (refs > 0 && !has) refsButNoDefs++;
  }
  console.log(name, { total: list.length, withDefsKey, withRefs, refsButNoDefs });
}
