const g = await Bun.file('data/raw/googlesuper_tools.json').json();
const h = await Bun.file('data/raw/github_tools.json').json();
const all = [...g, ...h];

// 1. Count tools with any file_uploadable: true
function hasUploadable(obj) {
  if (!obj || typeof obj !== 'object') return false;
  if (obj.file_uploadable === true) return true;
  for (const v of Object.values(obj)) if (hasUploadable(v)) return true;
  return false;
}
const uploadable = all.filter(t => hasUploadable(t.inputParameters));
console.log('tools with a file_uploadable param:', uploadable.length);
console.log('examples:', uploadable.slice(0,5).map(t => t.slug));

// 2. Sniff for ALL_CAPS slug-like mentions in descriptions/parameter prose
const slugPattern = /\b([A-Z][A-Z0-9]+(?:_[A-Z0-9]+){2,})\b/g;
const trigger = /\b(use|see|via|from|returned by|call)\s+([A-Z][A-Z0-9]+(?:_[A-Z0-9]+){2,})\b/gi;
const slugSet = new Set(all.map(t => t.slug));
let triggerHits = 0, slugHits = 0, gmailVariants = 0, sample = [];
for (const t of all) {
  const blobs = [t.description];
  for (const [n, p] of Object.entries(t.inputParameters?.properties || {})) {
    if (p?.description) blobs.push(p.description);
  }
  for (const blob of blobs) {
    if (typeof blob !== 'string') continue;
    let m;
    const tre = new RegExp(trigger.source, 'gi');
    while ((m = tre.exec(blob))) {
      triggerHits++;
      const s = m[2];
      if (slugSet.has(s)) slugHits++;
      if (s.startsWith('GMAIL_')) {
        gmailVariants++;
        if (sample.length < 6) sample.push({mention: s, normalized: 'GOOGLESUPER_' + s.slice(6), normalizedExists: slugSet.has('GOOGLESUPER_' + s.slice(6))});
      }
    }
  }
}
console.log({triggerHits, slugHits, gmailVariants});
console.log('GMAIL_ samples:', sample);
"

