# Implement `src/extract.ts` — three-signal dependency extractor

## Context

We need to derive a tool-to-tool dependency graph from raw Composio JSON for the `googlesuper` (438 tools) and `github` (867 tools) toolkits. The extractor is the foundation of the whole project — graph quality, LLM augmentation, and visualization all consume its output. Output schemas in the raw data are name-only (`$ref` to undefined `$defs`), so we cannot reason from response payload structure. We must rely on three signals derived from inputs and prose.

**Ground-truth checks already done against `data/raw/*.json`:**
- All 44 hardcoded slugs in the spec exist in the dataset (0 missing).
- The trigger-pattern regex finds 151 mentions across descriptions; 14 direct slug matches; 36 `GMAIL_*` mentions that all normalize cleanly to existing `GOOGLESUPER_*` slugs.
- 11 tools carry a `file_uploadable: true` parameter — these are the consumers for the upload soft dep.

## Files modified

- [src/types.ts](src/types.ts) — add `DependencyEdge`, `DependencyConfidence`, `DependencyType`.
- [src/extract.ts](src/extract.ts) — replace stub with full implementation below.

No other files touched. `src/index.ts` is **not** modified by this task (the user will wire `extractDependencies` in a later step).

---

## Addition to `src/types.ts`

Append (do not replace existing content):

```ts
export type DependencyConfidence = "high" | "medium" | "low";
export type DependencyType = "hard" | "soft";

export interface DependencyEdge {
  from: string;           // producer tool slug
  to: string;             // consumer tool slug
  via: string;            // parameter name or token being passed
  confidence: DependencyConfidence;
  dependencyType: DependencyType;
  reason: string;         // one sentence explaining this edge
}
```

---

## Full implementation: `src/extract.ts`

```ts
// Extracts tool-to-tool dependency edges from raw Composio JSON using three
// signals: description-based slug mentions (high), a structural token
// taxonomy (medium), and hand-authored soft dependencies (low).

import { writeFileSync } from "fs";
import type { DependencyEdge, Tool } from "./types.ts";

// ------------------------------------------------------------
// Public API
// ------------------------------------------------------------

export function extractDependencies(tools: Tool[]): DependencyEdge[] {
  const slugs = new Set(tools.map((t) => t.slug));
  const edges: DependencyEdge[] = [
    ...extractDescriptionHints(tools, slugs),
    ...extractStructuralHints(tools, slugs),
    ...extractSoftHints(tools, slugs),
  ];
  return sortEdges(dedupeEdges(edges));
}

export function writeEdges(edges: DependencyEdge[], path: string): void {
  writeFileSync(path, JSON.stringify(edges, null, 2), "utf-8");
}

// ------------------------------------------------------------
// SIGNAL 1: description-based hints (high confidence, hard)
// ------------------------------------------------------------

const TRIGGER_RE =
  /\b(use|see|via|from|returned\s+by|call)\s+([A-Z][A-Z0-9]+(?:_[A-Z0-9]+){2,})\b/gi;

export function extractDescriptionHints(
  tools: Tool[],
  slugs: Set<string>
): DependencyEdge[] {
  const out: DependencyEdge[] = [];
  for (const tool of tools) {
    // Top-level tool description: producer named in prose, consumer is THIS tool.
    scanProse(tool.description, (mention) => {
      const from = normalizeSlug(mention, slugs);
      if (!from || from === tool.slug) return;
      out.push({
        from,
        to: tool.slug,
        via: "description",
        confidence: "high",
        dependencyType: "hard",
        reason: `${tool.slug} description names ${mention} as a precursor`,
      });
    });

    // Per-parameter description prose.
    for (const [paramName, schema] of Object.entries(
      tool.inputParameters.properties
    )) {
      scanProse(schema.description, (mention) => {
        const from = normalizeSlug(mention, slugs);
        if (!from || from === tool.slug) return;
        out.push({
          from,
          to: tool.slug,
          via: paramName,
          confidence: "high",
          dependencyType: "hard",
          reason: `${tool.slug}.${paramName} description names ${mention} as the producer`,
        });
      });
    }
  }
  return out;
}

function scanProse(prose: string | undefined, onMention: (slug: string) => void): void {
  if (!prose) return;
  const re = new RegExp(TRIGGER_RE.source, "gi");
  let m: RegExpExecArray | null;
  while ((m = re.exec(prose))) {
    onMention(m[2]);
  }
}

// "GMAIL_FOO" → "GOOGLESUPER_FOO" if that exists. Otherwise the mention itself
// only if it is a real slug. Else null (don't record an edge).
function normalizeSlug(mention: string, slugs: Set<string>): string | null {
  if (slugs.has(mention)) return mention;
  if (mention.startsWith("GMAIL_")) {
    const alt = "GOOGLESUPER_" + mention.slice("GMAIL_".length);
    if (slugs.has(alt)) return alt;
  }
  return null;
}

// ------------------------------------------------------------
// SIGNAL 2: structural / semantic heuristics (medium confidence, hard)
// ------------------------------------------------------------

type TokenFamily = {
  token: string;
  producers: string[];
  consumerCheck: (tool: Tool) => boolean;
};

const TOKEN_FAMILIES: TokenFamily[] = [
  {
    token: "owner+repo",
    producers: [
      "GITHUB_LIST_REPOSITORIES_FOR_THE_AUTHENTICATED_USER",
      "GITHUB_SEARCH_REPOSITORIES",
      "GITHUB_GET_A_REPOSITORY",
      "GITHUB_FIND_REPOSITORIES",
    ],
    consumerCheck: (t) =>
      requiresParam(t, "owner") && requiresParam(t, "repo"),
  },
  {
    token: "issue_number",
    producers: [
      "GITHUB_LIST_REPOSITORY_ISSUES",
      "GITHUB_CREATE_AN_ISSUE",
      "GITHUB_SEARCH_ISSUES_AND_PULL_REQUESTS",
    ],
    consumerCheck: (t) => hasParam(t, "issue_number"),
  },
  {
    token: "pull_number",
    producers: [
      "GITHUB_LIST_PULL_REQUESTS",
      "GITHUB_CREATE_A_PULL_REQUEST",
      "GITHUB_FIND_PULL_REQUESTS",
    ],
    consumerCheck: (t) => hasParam(t, "pull_number"),
  },
  {
    token: "release_id",
    producers: [
      "GITHUB_LIST_RELEASES",
      "GITHUB_CREATE_A_RELEASE",
      "GITHUB_GET_THE_LATEST_RELEASE",
    ],
    consumerCheck: (t) => hasParam(t, "release_id"),
  },
  {
    token: "workflow_id|run_id",
    producers: [
      "GITHUB_LIST_REPOSITORY_WORKFLOWS",
      "GITHUB_LIST_WORKFLOW_RUNS_FOR_A_REPOSITORY",
    ],
    consumerCheck: (t) => hasParam(t, "workflow_id") || hasParam(t, "run_id"),
  },
  {
    token: "comment_id",
    producers: [
      "GITHUB_LIST_ISSUE_COMMENTS",
      "GITHUB_CREATE_AN_ISSUE_COMMENT",
    ],
    consumerCheck: (t) => hasParam(t, "comment_id"),
  },
  {
    token: "branch|ref",
    producers: ["GITHUB_LIST_BRANCHES", "GITHUB_CREATE_A_REFERENCE"],
    consumerCheck: (t) => hasParam(t, "branch") || hasParam(t, "ref"),
  },
  {
    token: "thread_id",
    producers: [
      "GOOGLESUPER_LIST_THREADS",
      "GOOGLESUPER_FETCH_EMAILS",
      "GOOGLESUPER_FETCH_MESSAGE_BY_THREAD_ID",
    ],
    consumerCheck: (t) => hasParam(t, "thread_id"),
  },
  {
    token: "message_id",
    producers: [
      "GOOGLESUPER_SEND_EMAIL",
      "GOOGLESUPER_LIST_THREADS",
      "GOOGLESUPER_FETCH_EMAILS",
    ],
    consumerCheck: (t) => hasParam(t, "message_id"),
  },
  {
    token: "file_id",
    producers: [
      "GOOGLESUPER_CREATE_FILE",
      "GOOGLESUPER_FIND_FILE",
      "GOOGLESUPER_UPLOAD_FILE",
      "GOOGLESUPER_LIST_FILES",
    ],
    consumerCheck: (t) => hasParam(t, "file_id"),
  },
  {
    token: "calendar_id",
    producers: [
      "GOOGLESUPER_LIST_CALENDARS",
      "GOOGLESUPER_DUPLICATE_CALENDAR",
    ],
    consumerCheck: (t) => hasParam(t, "calendar_id"),
  },
  {
    token: "event_id",
    producers: [
      "GOOGLESUPER_CREATE_EVENT",
      "GOOGLESUPER_EVENTS_LIST",
