// ------------------------------------------------------------
// SIGNAL 3: hand-authored soft dependencies (low confidence, soft)
// ------------------------------------------------------------

type SoftRule = {
  consumer: string;          // exact slug, or "*" for wildcard with appliesTo
  producers: string[];
  via: string;
  reason: string;
  appliesTo?: (tool: Tool) => boolean;
};

const SOFT_RULES: SoftRule[] = [
