    ...extractDescriptionHints(tools, slugs),
    ...extractStructuralHints(tools, slugs),
    ...extractSoftHints(tools, slugs),
  ];
  return sortEdges(dedupeEdges(edges));
}

export function writeEdges(edges: DependencyEdge[], path: string): void {
  writeFileSync(path, JSON.stringify(edges, null, 2), "utf-8");
