function scanProse(prose: string | undefined, onMention: (slug: string) => void): void {
  if (!prose) return;
  const re = new RegExp(TRIGGER_RE.source, "gi");
  let m: RegExpExecArray | null;
  while ((m = re.exec(prose))) {
