    // Top-level tool description: producer named in prose, consumer is THIS tool.
    scanProse(tool.description, (mention) => {
      const from = normalizeSlug(mention, slugs);
      if (!from || from === tool.slug) return;
      out.push({
        from,
        to: tool.slug,
        via: "description",
        confidence: "high",
        dependencyType: "hard",
