  return edges.sort((a, b) => {
    if (a.from !== b.from) return a.from < b.from ? -1 : 1;
    if (a.to !== b.to) return a.to < b.to ? -1 : 1;
    if (a.via !== b.via) return a.via < b.via ? -1 : 1;
    return RANK[b.confidence] - RANK[a.confidence];
  });
}

