import { Composio } from "@composio/core";
import { writeFile } from "fs/promises";

// Bun auto-loads .env, but be explicit so it also works under node-style runners.
if (!process.env.COMPOSIO_API_KEY) {
  throw new Error("COMPOSIO_API_KEY missing — did you create .env?");
}

const composio = new Composio();

// raw tools are direct tools from composio without any wrapping based on providers
// provider wrappings are needed for executing tools
const googleTools = await composio.tools.getRawComposioTools({
  toolkits: ["googlesuper"],
  limit: 1000,
});
await writeFile(
  "data/raw/googlesuper_tools.json",
  JSON.stringify(googleTools, null, 2),
  "utf-8"
);
console.log(`googlesuper: ${googleTools.length} tools → data/raw/googlesuper_tools.json`);

const githubTools = await composio.tools.getRawComposioTools({
  toolkits: ["github"],
  limit: 1000,
});
await writeFile(
  "data/raw/github_tools.json",
  JSON.stringify(githubTools, null, 2),
  "utf-8"
);
console.log(`github: ${githubTools.length} tools → data/raw/github_tools.json`);

