// Renders data/graph.json as a self-contained dependency explorer at
// data/graph.html: searchable left panel + per-tool subgraph on the right.

import { readFileSync, writeFileSync } from "fs";

export function generateHtml(): void {
  const graph = JSON.parse(readFileSync("data/graph.json", "utf-8"));
  const payload = JSON.stringify({ nodes: graph.nodes, edges: graph.edges })
    .replace(/<\/script>/gi, "<\\/script>");
  writeFileSync("data/graph.html", HTML.replace("__GRAPH_DATA__", payload), "utf-8");
}

// Inline JS uses string concatenation (not template literals) so the outer
// TS template literal doesn't need backtick/${} escaping.
const HTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Composio dependency explorer</title>
<style>
  html, body { margin: 0; height: 100%; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #f4f4f5; color: #18181b; }
  .app { display: flex; height: 100vh; }

  .sidebar { width: 300px; background: #fff; border-right: 1px solid #e4e4e7; display: flex; flex-direction: column; flex-shrink: 0; }
  .filter { padding: 12px 16px; border-bottom: 1px solid #e4e4e7; }
  .filter input { width: 100%; padding: 8px 10px; border: 1px solid #d4d4d8; border-radius: 6px; font-size: 13px; box-sizing: border-box; font-family: inherit; }
  .filter input:focus { outline: none; border-color: #4285F4; }
