var gs = sorted.filter(function (n) { return n.toolkit === "googlesuper"; });
var gh = sorted.filter(function (n) { return n.toolkit === "github"; });

var listEl = document.getElementById("list");
var qEl = document.getElementById("q");
var selected = null;

