// Renders data/graph.json as a self-contained D3 force-directed HTML page
// at data/graph.html (D3 loaded from CDN; data inlined).

import { readFileSync, writeFileSync } from "fs";

export function generateHtml(): void {
  const graph = JSON.parse(readFileSync("data/graph.json", "utf-8"));
  const payload = JSON.stringify({ nodes: graph.nodes, edges: graph.edges })
    // Defensive: in case any string in the data ever contains </script>.
    .replace(/<\/script>/gi, "<\\/script>");
  writeFileSync("data/graph.html", HTML.replace("__GRAPH_DATA__", payload), "utf-8");
}

const HTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Composio tool dependency graph</title>
<style>
  html, body { margin: 0; height: 100%; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #fafafa; }
  svg { width: 100vw; height: 100vh; display: block; }
  .link { stroke: #999; stroke-opacity: 0.35; }
  .node { stroke: #fff; stroke-width: 1px; cursor: pointer; }
  .tooltip {
    position: absolute; pointer-events: none;
    background: rgba(20,20,20,0.92); color: #fff;
    padding: 6px 10px; border-radius: 4px;
    font-size: 12px; max-width: 360px;
    opacity: 0; transition: opacity 0.12s;
  }
</style>
</head>
<body>
<svg></svg>
<div class="tooltip" id="tt"></div>
<script src="https://d3js.org/d3.v7.min.js"></script>
<script>
const data = __GRAPH_DATA__;
const colors = { googlesuper: "#4285F4", github: "#24292e" };
const width = window.innerWidth, height = window.innerHeight;

const svg = d3.select("svg").attr("viewBox", [0, 0, width, height]);
const root = svg.append("g");
svg.call(d3.zoom().scaleExtent([0.1, 8]).on("zoom", e => root.attr("transform", e.transform)));

const links = data.edges.map(e => ({ source: e.from, target: e.to, ...e }));
const nodes = data.nodes.map(n => ({ ...n }));

const sim = d3.forceSimulation(nodes)
  .force("link", d3.forceLink(links).id(d => d.id).distance(70).strength(0.2))
  .force("charge", d3.forceManyBody().strength(-90))
  .force("center", d3.forceCenter(width / 2, height / 2))
  .force("collide", d3.forceCollide().radius(d => 4 + Math.sqrt(d.inDegree + d.outDegree) + 2));

const link = root.append("g")
  .selectAll("line").data(links).join("line").attr("class", "link");

const node = root.append("g")
  .selectAll("circle").data(nodes).join("circle")
  .attr("class", "node")
  .attr("r", d => 4 + Math.sqrt(d.inDegree + d.outDegree))
  .attr("fill", d => colors[d.toolkit] || "#888")
  .call(drag(sim));

const tt = d3.select("#tt");
node
  .on("mouseover", (e, d) => tt.style("opacity", 1)
    .html(\`<b>\${d.id}</b><br>\${d.name}<br>in: \${d.inDegree}, out: \${d.outDegree}\`)
    .style("left", (e.pageX + 12) + "px").style("top", (e.pageY + 12) + "px"))
  .on("mousemove", e => tt.style("left", (e.pageX + 12) + "px").style("top", (e.pageY + 12) + "px"))
  .on("mouseout", () => tt.style("opacity", 0));

sim.on("tick", () => {
  link.attr("x1", d => d.source.x).attr("y1", d => d.source.y)
      .attr("x2", d => d.target.x).attr("y2", d => d.target.y);
  node.attr("cx", d => d.x).attr("cy", d => d.y);
});

function drag(sim) {
  return d3.drag()
    .on("start", (e, d) => { if (!e.active) sim.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; })
    .on("drag",  (e, d) => { d.fx = e.x; d.fy = e.y; })
    .on("end",   (e, d) => { if (!e.active) sim.alphaTarget(0); d.fx = null; d.fy = null; });
}
</script>
</body>
</html>
`;

