const g = await Bun.file('data/raw/googlesuper_tools.json').json();
const h = await Bun.file('data/raw/github_tools.json').json();
const edges = await Bun.file('data/edges.json').json();

const used = new Set();
for (const e of edges) { used.add(e.from); used.add(e.to); }

const isStartingPoint = (slug) => /(?:_LIST_|_SEARCH_|_AUTHENTICATED_USER\$|_FOR_THE_AUTHENTICATED_USER\$|_FETCH_|_FIND_|_GET_THE_LATEST_)/.test(slug);

function suggestiveScore(tool) {
  const props = tool.inputParameters?.properties || {};
  const required = new Set(tool.inputParameters?.required || []);
  let score = 0;
  for (const [name, schema] of Object.entries(props)) {
    const lname = name.toLowerCase();
    if (lname.endsWith('_id') || lname === 'id') score += required.has(name) ? 3 : 1;
    if (['email','recipient','recipient_email','username','login','owner','repo','path','name','query'].includes(lname)) score += required.has(name) ? 2 : 1;
  }
  return score;
}

function pickExamples(tools, label) {
  const orphans = tools.filter(t => !used.has(t.slug));
  const orphansSet = orphans.map(t => t.slug);
  const suggestive = orphans
    .filter(t => !isStartingPoint(t.slug))
    .map(t => ({ slug: t.slug, score: suggestiveScore(t), name: t.name }))
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score);
  console.log('=== ' + label + ' ===');
  console.log('total tools:', tools.length, '| orphan tools:', orphans.length);
  console.log('top 10 orphans that look like they should have deps:');
  for (const x of suggestive.slice(0, 10)) {
    console.log('  ' + x.slug + ' (score ' + x.score + ') — ' + x.name);
  }
}

