~/.bun/bin/bun -e "
const edges = await Bun.file('data/edges.json').json();
const g = await Bun.file('data/raw/googlesuper_tools.json').json();
const h = await Bun.file('data/raw/github_tools.json').json();

const used = new Set();
for (const e of edges) { used.add(e.from); used.add(e.to); }
const gsConn = g.filter(t => used.has(t.slug)).length;
const ghConn = h.filter(t => used.has(t.slug)).length;
const gsOrphan = g.length - gsConn;
const ghOrphan = h.length - ghConn;

const conf = {high:0, medium:0, low:0};
const dep = {hard:0, soft:0};
for (const e of edges) { conf[e.confidence]++; dep[e.dependencyType]++; }

console.log('total edges:', edges.length);
console.log('confidence:', conf);
console.log('dep type:', dep);
console.log('googlesuper: total=' + g.length + ' connected=' + gsConn + ' orphan=' + gsOrphan + ' (' + Math.round(100*gsOrphan/g.length) + '%)');
console.log('github:      total=' + h.length + ' connected=' + ghConn + ' orphan=' + ghOrphan + ' (' + Math.round(100*ghOrphan/h.length) + '%)');
console.log('overall:     total=' + (g.length+h.length) + ' connected=' + used.size + ' orphan=' + (g.length+h.length-used.size));
"

